                  for line in slip.lines],
    }


def low_stock_body(product: LowStockProduct) -> dict[str, Any]:
    return {"sku": product.sku, "name": product.name, "on_hand": product.on_hand}


class FulfilmentController:
    def __init__(self, service: FulfilmentService) -> None:
        self._service = service

